import { Request, Response } from 'express';
import { CreateProjectUseCase } from '../../../application/use-cases/CreateProjectUseCase';
import { RequestReader } from '../RequestReader';

export class ProjectController {
  constructor(private readonly createProject: CreateProjectUseCase) {}

  create = async (req: Request, res: Response): Promise<void> => {
    const body = new RequestReader(req.body);
    const project = await this.createProject.execute({
      name: body.requiredString('name'),
      description: body.optionalString('description'),
    });
    res.status(201).json(project);
  };
}

